INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch06$PT138-S2-Q26$batch06$, 138, 2, 26, $batch06$Method$batch06$, $batch06$Sarah: When commercial fishing boats with permits to fish for certain species accidentally catch a type of fish for which they have no permit, the latter must be thrown back. This is a very wasteful practice because many, if not most, of the rejected fish do not survive. Fishing permits should therefore be altered so that fishers can keep fish caught accidentally. Amar: Making it legal to keep those fish would probably lead to a lot more "accidents."$batch06$, $batch06$The technique Amar uses in responding to Sarah's argument is to$batch06$, $batch06$D$batch06$, true, $batch06$Batch 06; question text from local bank.$batch06$ FROM lr_sections s WHERE s.preptest=138 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT138-S2-Q26$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$A$batch06$, $batch06$question whether Sarah's recommendation can be put into practice$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT138-S2-Q26$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$A$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$B$batch06$, $batch06$point out that Sarah used a crucial term in two distinct senses$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT138-S2-Q26$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$B$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$C$batch06$, $batch06$allude to a factor that supposedly strengthens the case for Sarah's recommendation$batch06$, $batch06$Opposite$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT138-S2-Q26$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$C$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$D$batch06$, $batch06$contend that Sarah's recommendation has an important negative consequence$batch06$, $batch06$Correct$batch06$, true FROM lr_questions q WHERE q.qid=$batch06$PT138-S2-Q26$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$D$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$E$batch06$, $batch06$maintain that Sarah overlooks important lessons from past policies$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT138-S2-Q26$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$E$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT138-S2-Q26$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Amar, implied) Sarah's rule change is a bad idea.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Letting fishers keep accidental catches would probably lead to many more "accidents."$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Look at Amar's scare quotes around "accidents." He is saying fishers would start catching the wrong fish on purpose once they could keep them. Sarah's fix to reduce waste would create a new problem: more catching of fish without permits.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Pointing out a negative consequence of Sarah's recommendation.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT138-S2-Q26$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Amar does not say the rule change cannot be carried out. He says carrying it out would backfire.$batch06$), ($batch06$B$batch06$, $batch06$"Accidents" in quotes is Amar's own word for disguised intent. He is not accusing Sarah of using a term two ways.$batch06$), ($batch06$C$batch06$, $batch06$Amar's point weakens Sarah's case. It does not strengthen it.$batch06$), ($batch06$D$batch06$, $batch06$The negative consequence is more deliberate catching passed off as accidents.$batch06$), ($batch06$E$batch06$, $batch06$No past policies are discussed.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT138-S2-Q26$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
